        end

        function r = spd_matrix_fn(self, x, kind)
            % Batched `logm` / `expm` / `sqrtm` / `invsqrtm` over `[batch, n, n]`.
            [rc, r0_0] = rlx_mex('rlx_graph_spd_matrix_fn', self.h, x, kind);
            rlx.internal.check(rc);
            r = r0_0;
        end

        function r = spd_batch_norm(self, x, gamma, eps, varargin)
            % Riemannian batch norm → `(normalized, batch_mean)`.
            o = rlx.internal.opts(varargin, {'iters', 'tol'}, {20, 1e-6});
            [rc, r0_0, r1_0] = rlx_mex('rlx_graph_spd_batch_norm', self.h, x, gamma, eps, o.iters, o.tol);
            rlx.internal.check(rc);
            r = struct();
            r.first = r0_0;
            r.second = r1_0;
        end

        function r = spd_batch_norm_transport(self, x, mean, gamma, eps)
            % The transport step of SPD batch norm against a given `mean`.
            [rc, r0_0] = rlx_mex('rlx_graph_spd_batch_norm_transport', self.h, x, mean, gamma, eps);
            rlx.internal.check(rc);
            r = r0_0;
        end

        function r = spd_karcher_mean(self, x, varargin)
            % The Fréchet mean under the affine-invariant metric.
            o = rlx.internal.opts(varargin, {'iters', 'tol', 'weights'}, {20, 1e-6, []});
            [rc, r0_0] = rlx_mex('rlx_graph_spd_karcher_mean', self.h, x, o.iters, o.tol, rlx.internal.node(o.weights));
            rlx.internal.check(rc);
            r = r0_0;
        end

        function r = spectral_reeig(self, x, sweeps, eps)
            % ReEig by Jacobi sweeps (no LAPACK) — runs on every backend.
            [rc, r0_0] = rlx_mex('rlx_graph_spectral_reeig', self.h, x, sweeps, eps);
            rlx.internal.check(rc);
            r = r0_0;
        end

        function r = spectral_logeig(self, x, sweeps, eps)
            [rc, r0_0] = rlx_mex('rlx_graph_spectral_logeig', self.h, x, sweeps, eps);
            rlx.internal.check(rc);
            r = r0_0;
        end

    end
end
